begin;
do $$declare actor uuid;adm uuid;before_count bigint;request uuid:=gen_random_uuid();post_id uuid;second uuid;u text;begin
 select user_id into adm from public.cineo_admins limit 1;
 select id into actor from auth.users where id<>adm and not exists(select 1 from public.cineo_follows where user_id=id and kind='creator' and target=adm::text) and not exists(select 1 from public.cineo_blocks where(user_id=id and target_id=adm)or(user_id=adm and target_id=id)) limit 1;
 if actor is null then raise exception 'No isolated follower fixture';end if;
 insert into public.cineo_profiles(user_id,name) values(actor,'Profile fixture'),(adm,'Owner fixture') on conflict(user_id) do nothing;
 select username into u from public.cineo_profiles where user_id=actor;
 begin update public.cineo_profiles set username=u where user_id=adm;raise exception 'DUPLICATE_USERNAME';exception when unique_violation then null;end;
 before_count:=(public.cineo_profile_counts(adm)->>'followers')::bigint;
 perform public.cineo_profile_follow(actor,adm,true);perform public.cineo_profile_follow(actor,adm,true);
 if (public.cineo_profile_counts(adm)->>'followers')::bigint<>before_count+1 then raise exception 'Follow was duplicated';end if;
 if not exists(select 1 from jsonb_array_elements(public.cineo_profile_people(adm,adm,'followers',0))x where x->>'user_id'=actor::text) then raise exception 'Follower directory missing profile';end if;
 begin perform public.cineo_profile_follow(actor,actor,true);raise exception 'SELF_FOLLOW';exception when others then if sqlerrm='SELF_FOLLOW' then raise;end if;end;
 perform public.cineo_profile_follow(actor,adm,false);if (public.cineo_profile_counts(adm)->>'followers')::bigint<>before_count then raise exception 'Unfollow failed';end if;
 insert into public.cineo_blocks(user_id,target_id) values(actor,adm) on conflict do nothing;
 begin perform public.cineo_profile_follow(actor,adm,true);raise exception 'BLOCKED_FOLLOW';exception when others then if sqlerrm='BLOCKED_FOLLOW' then raise;end if;end;
 insert into public.cineo_creator_accounts(user_id,first_name,last_name,birth_date,status,approved_at) values(actor,'Post','Fixture','1990-01-01','approved',now()) on conflict(user_id) do update set status='approved';
 post_id:=(public.cineo_profile_post(actor,request,'Mensagem de teste em análise',null)->>'id')::uuid;
 second:=(public.cineo_profile_post(actor,request,'Mensagem de teste em análise',null)->>'id')::uuid;
 if post_id<>second then raise exception 'Post retry created a duplicate';end if;
 if not exists(select 1 from public.cineo_profile_posts where id=post_id and status='pending') then raise exception 'Post bypassed moderation';end if;
 begin perform public.cineo_review_profile_post(actor,post_id,'approved','');raise exception 'UNAUTHORIZED_POST_REVIEW';exception when others then if sqlerrm='UNAUTHORIZED_POST_REVIEW' then raise;end if;end;
 perform public.cineo_review_profile_post(adm,post_id,'rejected','Revise a mensagem');
 if not exists(select 1 from public.cineo_profile_posts where id=post_id and status='rejected' and reason='Revise a mensagem') then raise exception 'Rejection lost reason';end if;
 begin perform public.cineo_review_profile_post(adm,post_id,'approved','');raise exception 'DUPLICATE_POST_REVIEW';exception when others then if sqlerrm='DUPLICATE_POST_REVIEW' then raise;end if;end;
 post_id:=(public.cineo_profile_post(actor,gen_random_uuid(),'Mensagem aprovada de teste',null)->>'id')::uuid;perform public.cineo_review_profile_post(adm,post_id,'approved','');
 if not exists(select 1 from public.cineo_profile_posts where id=post_id and status='approved') then raise exception 'Post was not approved';end if;
end$$;
rollback;
